    '32025003NOPV_PCP PCO_01162025_(23-264381)': {
        Q[7]: '6',
        Q[8]: '192.473, 192.605, 192.615, 192.706, 192.907, 192.947',
        Q[11]: 'NOT_FOUND',
    },
}
for doc_name,vals in overrides.items():
    answers[doc_name].update(vals)

# Final normalization.
for doc_name,row in answers.items():
    for q in questions:
        row.setdefault(q,'NOT_FOUND')
        if row[q] is None or row[q]=='':
            row[q]='NOT_FOUND'
        else:
            row[q]=str(row[q]).strip()

out={'answers':answers}
# Validate schema.
assert set(out['answers'].keys())=={d['doc_name'] for d in obj['documents']}
for doc_name,row in out['answers'].items():
    assert set(row.keys())==set(questions)
OUTPUT.write_text(json.dumps(out, indent=2, ensure_ascii=False)+\"\\n\", encoding='utf-8')
print('wrote', OUTPUT)
# quick residual report
not_found_counts={q:sum(1 for d in answers.values() if d[q]=='NOT_FOUND') for q in questions}
for q,c in not_found_counts.items():
    print(c,q)
